import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Stack,
    TextField,
    Tooltip,
    Typography,
    useMediaQuery,
    useTheme,
} from '@mui/material'
import Close from 'mdi-material-ui/Close'
import Plus from 'mdi-material-ui/Plus'
import type { ChangeEvent, FormEvent, KeyboardEvent } from 'react'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { CardDraft, CardTypeConfig, StateConfig } from '../../../data/data_types'
import { useCardCreationState } from '../../hooks/use_card_creation_state'
import { CardTypePillGroup } from './card_type_pill_group'
import { NewCardMarkdownEditor } from './new_card_markdown_editor'
import { projectSessionService } from '../../../services/project/project_session_service'
import { dialogService } from '../../../services/dialog_service'
import { NewCardColumnPicker } from './new_card_column_picker'
import { MarkdownAttachmentControl } from '../../editor/markdown_attachment_control'
import { attachFilesToNewCardMarkdown } from '../../../services/attachments/new_card_attachment_workflow'

const DIALOG_WIDTH = 480
const DISCARD_CARD_MESSAGE = 'Discard this new card draft?'

function attachFilesToNewCardDraft(files: File[]) {
    void attachFilesToNewCardMarkdown(files, projectSessionService.newCardMarkdownDraft.requestInsertion).catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Files could not be attached' })
    })
}

interface NewCardDialogProps {
    cardBodyTemplate: string
    cardTypes: CardTypeConfig[]
    initialTargetStatus: string
    isLoading: boolean
    isProjectOpen: boolean
    open: boolean
    onClose: () => void
    onCreateCard: (draft: CardDraft, initialState: string) => Promise<void>
    states: StateConfig[]
}

/** Responsive form for creating a card in a selected board column. */
export function NewCardDialog(props: NewCardDialogProps) {
    const {
        cardBodyTemplate,
        cardTypes,
        initialTargetStatus,
        isLoading,
        isProjectOpen,
        onClose,
        onCreateCard,
        open,
        states,
    } = props
    const { isCreatingCard } = useCardCreationState()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const wasOpenRef = useRef(false)
    const [isInsertedTemplateUntouched, setIsInsertedTemplateUntouched] = useState(false)
    const [targetStatus, setTargetStatus] = useState('')
    const [title, setTitle] = useState('')
    const [type, setType] = useState('')
    const defaultType = cardTypes[0]?.type ?? ''
    const defaultStatus = states[0]?.state ?? ''
    const selectedType = cardTypes.some((typeConfig) => typeConfig.type === type) ? type : defaultType
    const selectedStatus = states.some((stateConfig) => stateConfig.state === targetStatus) ? targetStatus : defaultStatus
    const isSubmitDisabled = !isProjectOpen || title.trim().length === 0
        || selectedType.length === 0 || selectedStatus.length === 0 || isLoading || isCreatingCard

    const resetForm = () => {
        projectSessionService.newCardMarkdownDraft.replace('')
        setIsInsertedTemplateUntouched(false)
        setTargetStatus(initialTargetStatus)
        setTitle('')
        setType(defaultType)
    }

    useEffect(() => {
        if ((open && !wasOpenRef.current) || !isProjectOpen) {
            projectSessionService.newCardMarkdownDraft.replace('')
            setIsInsertedTemplateUntouched(false)
            setTargetStatus(initialTargetStatus)
            setTitle('')
            setType(defaultType)
        }
        wasOpenRef.current = open && isProjectOpen
    }, [defaultType, initialTargetStatus, isProjectOpen, open])

    const closeDialog = async () => {
        const body = projectSessionService.newCardMarkdownDraft.getSnapshot()
        const isDirty = title.length > 0
            || body.length > 0
            || selectedType !== defaultType
            || selectedStatus !== initialTargetStatus
            || projectSessionService.hasNewCardDraftImages()
        if (isDirty && !window.confirm(DISCARD_CARD_MESSAGE)) return

        try {
            await projectSessionService.discardNewCardDraftImages()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Pasted draft images could not be removed' })
            return
        }
        resetForm()
        onClose()
    }

    const handleDialogClose = () => {
        void closeDialog()
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitle(event.target.value)
    }

    const handleBodyDirtyChange = useCallback((dirty: boolean) => {
        if (dirty) setIsInsertedTemplateUntouched(false)
    }, [])

    const handleTemplateClick = () => {
        const body = projectSessionService.newCardMarkdownDraft.getSnapshot()
        if (isInsertedTemplateUntouched && body === cardBodyTemplate) {
            projectSessionService.newCardMarkdownDraft.replace('')
            setIsInsertedTemplateUntouched(false)

            return
        }

        const nextBody = body.length > 0 ? `${body}\n\n${cardBodyTemplate}` : cardBodyTemplate
        projectSessionService.newCardMarkdownDraft.replace(nextBody)
        setIsInsertedTemplateUntouched(body.length === 0)
    }

    const handleCreateClick = async () => {
        if (isSubmitDisabled) return

        await projectSessionService.waitForNewCardImageSaves()
        const body = projectSessionService.newCardMarkdownDraft.getSnapshot()
        const draft: CardDraft = {
            body,
            bodyIncludesTemplate: true,
            title: title.trim(),
            type: selectedType,
        }
        try {
            await onCreateCard(draft, selectedStatus)
        } catch {
            return
        }
        resetForm()
    }

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        await handleCreateClick()
    }

    const handleFormKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key !== 'Escape') return

        event.preventDefault()
        void closeDialog()
    }

    const handleFormKeyDownCapture = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key !== 'Enter' || !event.ctrlKey) return

        event.preventDefault()
        event.stopPropagation()
        void handleCreateClick()
    }

    const templateButtonLabel = isInsertedTemplateUntouched ? 'Clear' : 'Template'
    const createButton = (
        <Button aria-label="Create card" disabled={isSubmitDisabled} type="submit" variant="contained">
            <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                <Plus sx={{ fontSize: 17 }} />
                <span>Add</span>
                {!isMobile ? (
                    <Box
                        component="span"
                        sx={{
                            bgcolor: 'rgba(255,255,255,0.18)',
                            borderRadius: '5px',
                            fontSize: 10.5,
                            fontWeight: 600,
                            px: 0.625,
                            py: 0.25,
                        }}
                    >
                        Ctrl+â†µ
                    </Box>
                ) : null}
            </Stack>
        </Button>
    )

    return (
        <Dialog
            aria-labelledby="new-card-dialog-heading"
            fullScreen={isMobile}
            maxWidth={false}
            onClose={handleDialogClose}
            open={open}
            slotProps={{
                backdrop: { sx: { backdropFilter: 'blur(2px)', backgroundColor: 'rgba(16, 24, 40, 0.45)' } },
                paper: {
                    sx: {
                        border: isMobile ? 0 : 1,
                        borderColor: 'divider',
                        borderRadius: isMobile ? 0 : '14px',
                        boxShadow: isMobile ? 'none' : '0 24px 60px rgba(16,24,40,0.28)',
                        height: isMobile ? '100dvh' : 'auto',
                        maxHeight: isMobile ? '100dvh' : 'calc(100dvh - 32px)',
                        maxWidth: isMobile ? '100%' : 'calc(100% - 32px)',
                        overflow: 'hidden',
                        width: isMobile ? '100%' : DIALOG_WIDTH,
                    },
                },
            }}
        >
            <Box
                component="form"
                onKeyDown={handleFormKeyDown}
                onKeyDownCapture={handleFormKeyDownCapture}
                onSubmit={handleSubmit}
                sx={{ display: 'flex', flexDirection: 'column', height: isMobile ? '100%' : 'auto', maxHeight: '100dvh', minHeight: 0 }}
            >
                <DialogTitle
                    component="div"
                    id="new-card-dialog-header"
                    sx={{
                        alignItems: 'center',
                        borderBottom: 1,
                        borderColor: 'divider',
                        display: 'flex',
                        flexShrink: 0,
                        gap: 1.25,
                        minHeight: isMobile ? 56 : 62,
                        px: isMobile ? 1 : 2.25,
                        py: 1,
                    }}
                >
                    {isMobile ? (
                        <Button onClick={handleDialogClose} sx={{ minHeight: 44, minWidth: 72 }} type="button" variant="text">
                            Cancel
                        </Button>
                    ) : (
                        <Box
                            sx={{
                                alignItems: 'center',
                                bgcolor: 'custom.primaryBg',
                                borderRadius: 1,
                                color: 'primary.main',
                                display: 'flex',
                                height: 30,
                                justifyContent: 'center',
                                width: 30,
                            }}
                        >
                            <Plus sx={{ fontSize: 18 }} />
                        </Box>
                    )}
                    <Typography
                        component="h2"
                        id="new-card-dialog-heading"
                        sx={{
                            flex: 1,
                            fontSize: isMobile ? 16 : 15.5,
                            fontWeight: 700,
                            textAlign: isMobile ? 'center' : 'left',
                        }}
                    >
                        New card
                    </Typography>
                    {isMobile ? (
                        <Button disabled={isSubmitDisabled} sx={{ minHeight: 44, minWidth: 72 }} type="submit" variant="text">
                            Create
                        </Button>
                    ) : (
                        <Tooltip title="Close">
                            <IconButton aria-label="Close" onClick={handleDialogClose} size="small" sx={{ height: 30, width: 30 }}>
                                <Close sx={{ fontSize: 17 }} />
                            </IconButton>
                        </Tooltip>
                    )}
                </DialogTitle>
                <DialogContent
                    data-testid="new-card-dialog-content"
                    sx={{
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                        gap: isMobile ? 2.25 : 2,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 2.25 : 2.25,
                    }}
                >
                    <TextField
                        autoFocus
                        fullWidth
                        id="new-card-title"
                        onChange={handleTitleChange}
                        placeholder="Card titleâ€¦"
                        slotProps={{ htmlInput: { 'aria-label': 'Title' } }}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                borderRadius: isMobile ? '11px' : '9px',
                                mt: 1,
                                height: isMobile ? 48 : 46,
                                '&.Mui-focused': { boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}` },
                                '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderWidth: 1 },
                                '& .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderStrong' },
                            },
                            '& input': {
                                fontSize: isMobile ? 18 : 17,
                                fontWeight: 600,
                            },
                        }}
                        value={title}
                        variant="outlined"
                    />
                    <CardTypePillGroup
                        cardTypes={cardTypes}
                        isMobile={isMobile}
                        onChange={setType}
                        selectedType={selectedType}
                    />
                    <Stack spacing={isMobile ? 1.125 : 0.875}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <Typography color="text.secondary" id="new-card-description-label" sx={{ fontSize: 12, fontWeight: 600 }}>
                                Description
                            </Typography>
                            {!isMobile ? (
                                <Typography color="custom.text3" sx={{ fontSize: 11.5 }}>
                                    Markdown
                                </Typography>
                            ) : null}
                            <Box sx={{ flex: 1 }} />
                            <Button
                                disabled={cardBodyTemplate.length === 0}
                                onClick={handleTemplateClick}
                                size="small"
                                sx={{ minHeight: isMobile ? 44 : 30 }}
                                type="button"
                                variant="outlined"
                            >
                                {templateButtonLabel}
                            </Button>
                        </Stack>
                        <Box
                            aria-labelledby="new-card-description-label"
                            data-testid="new-card-description"
                            role="group"
                            sx={{
                                bgcolor: 'background.paper',
                                border: 1,
                                borderColor: 'custom.borderStrong',
                                borderRadius: isMobile ? '11px' : '9px',
                                boxSizing: 'border-box',
                                color: 'text.primary',
                                height: isMobile ? 260 : 270,
                                minHeight: isMobile ? 260 : 270,
                                outline: 'none',
                                overflow: 'auto',
                                resize: isMobile ? 'none' : 'vertical',
                                width: '100%',
                                '&:focus-within': {
                                    borderColor: 'primary.main',
                                    boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}`,
                                },
                                '&:hover:not(:focus-within)': { borderColor: 'custom.borderHover' },
                                '& > [data-sticky-toolbar]': { minHeight: '100%' },
                                '& .light-theme, & .dark-theme': { minHeight: '100%' },
                                '& .mdxeditor-content': {
                                    boxSizing: 'border-box',
                                    minHeight: isMobile ? 258 : 268,
                                    p: 1.625,
                                },
                            }}
                        >
                            <NewCardMarkdownEditor
                                draft={projectSessionService.newCardMarkdownDraft}
                                onDirtyChange={handleBodyDirtyChange}
                            />
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions
                    sx={{
                        alignItems: 'stretch',
                        bgcolor: 'background.default',
                        borderTop: 1,
                        borderColor: 'divider',
                        flexDirection: isMobile ? 'column' : 'row',
                        flexShrink: 0,
                        gap: isMobile ? 1.5 : 1,
                        justifyContent: 'space-between',
                        m: 0,
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 1.5 : 1.5,
                        pb: isMobile ? 'max(12px, env(safe-area-inset-bottom))' : 1.5,
                    }}
                >
                    <Stack
                        data-testid="new-card-footer-start"
                        direction="row"
                        spacing={1}
                        sx={{ alignItems: 'center', minWidth: 0, width: isMobile ? '100%' : 'auto' }}
                    >
                        <MarkdownAttachmentControl disabled={false} onFiles={attachFilesToNewCardDraft} />
                        <NewCardColumnPicker
                            isMobile={isMobile}
                            onChange={setTargetStatus}
                            selectedStatus={selectedStatus}
                            states={states}
                        />
                    </Stack>
                    {isMobile ? createButton : (
                        <Stack direction="row" spacing={1}>
                            <Button onClick={handleDialogClose} type="button" variant="outlined">
                                Cancel
                            </Button>
                            {createButton}
                        </Stack>
                    )}
                </DialogActions>
            </Box>
        </Dialog>
    )
}

import { memo } from 'react'
import { MarkdownEditor } from '../../editor/markdown_editor'
import { projectSessionService } from '../../../services/project/project_session_service'
import { attachFilesToNewCardMarkdown } from '../../../services/attachments/new_card_attachment_workflow'
import type { MarkdownDraft } from '../../../services/markdown/markdown_draft'

interface NewCardMarkdownEditorProps {
    draft: MarkdownDraft
    onDirtyChange: (dirty: boolean) => void
}

const handleImagePaste = (file: File, insertMarkdown: (markdown: string) => void) => (
    projectSessionService.pasteNewCardImage(file, insertMarkdown)
)
const handleAttachments = (files: File[], insertMarkdown: (markdown: string) => void) => (
    attachFilesToNewCardMarkdown(files, insertMarkdown)
)

/** Lifetime-stable Markdown editor boundary for a new-card draft. */
export const NewCardMarkdownEditor = memo(function NewCardMarkdownEditor(props: NewCardMarkdownEditorProps) {
    const { draft, onDirtyChange } = props

    return (
        <MarkdownEditor
            attachmentHandler={handleAttachments}
            draft={draft}
            hideAttachmentControl
            hideToolbar
            imagePasteHandler={handleImagePaste}
            onDirtyChange={onDirtyChange}
        />
    )
})

import { IconButton, Tooltip } from '@mui/material'
import Paperclip from 'mdi-material-ui/Paperclip'
import { useRef, type ChangeEvent } from 'react'

interface MarkdownAttachmentControlProps {
    disabled: boolean
    onFiles: (files: File[]) => void
}

/** Placement-neutral paperclip file picker for Markdown attachment workflows. */
export function MarkdownAttachmentControl(props: MarkdownAttachmentControlProps) {
    const { disabled, onFiles } = props
    const inputRef = useRef<HTMLInputElement>(null)
    const openFilePicker = () => inputRef.current?.click()
    const handleFilesSelected = (event: ChangeEvent<HTMLInputElement>) => {
        const files = [...(event.target.files ?? [])]
        event.target.value = ''
        if (files.length > 0) onFiles(files)
    }

    return (
        <>
            <Tooltip title="Attach files">
                <span>
                    <IconButton aria-label="Attach files" disabled={disabled} onClick={openFilePicker} size="small">
                        <Paperclip sx={{ fontSize: 18 }} />
                    </IconButton>
                </span>
            </Tooltip>
            <input hidden multiple onChange={handleFilesSelected} ref={inputRef} type="file" />
        </>
    )
}

import { copyAndApplyAttachments } from '../data/card_attachment_operations'
import { projectSessionService } from '../project/project_session_service'
import { attachmentChoiceService } from './attachment_choice_service'
import { attachmentMarkdown, type AttachmentMarkdownInserter } from './attachment_workflow'

/** Runs Markdown attachment choice with new-card draft ownership. */
export async function attachFilesToNewCardMarkdown(files: File[], insertMarkdown: AttachmentMarkdownInserter) {
    const selection = await attachmentChoiceService.choose(files)
    if (!selection) return

    if (selection.choice === 'original') {
        if (!selection.originalPaths) throw new Error('Original attachment paths are unavailable')
        await insertMarkdown(attachmentMarkdown(files, selection.originalPaths, true))
        return
    }

    await copyAndApplyAttachments(
        files,
        (selectedFiles) => projectSessionService.copyNewCardAttachments(selectedFiles),
        async (attachments) => insertMarkdown(attachmentMarkdown(
            files,
            attachments.map(({ fileName }) => fileName),
            false,
        )),
        (paths) => projectSessionService.deleteNewCardDraftAttachments(paths),
    )
}

import type { SavedCardAttachment } from '../data/card_attachment_operations'
import { copyAndApplyAttachments } from '../data/card_attachment_operations'
import { dataService } from '../data/data_service'
import { attachmentChoiceService } from './attachment_choice_service'
import { getOriginalFilePaths } from '../../data/electron_file_bridge'

export type AttachmentMarkdownInserter = (markdown: string) => void | Promise<void>

function escapeMarkdownLabel(label: string) {
    return label.replace(/([\\\]])/gu, '\\$1')
}

/** Converts a trusted absolute filesystem path to Markdown's absolute file URL form. */
export function absoluteFileUrl(filePath: string) {
    const normalizedPath = filePath.replace(/\\/gu, '/')
    const encodedPath = encodeURI(normalizedPath).replace(/#/gu, '%23').replace(/\?/gu, '%3F')
    if (normalizedPath.startsWith('//')) return `file:${encodedPath}`
    if (/^[a-z]:\//iu.test(normalizedPath)) return `file:///${encodedPath}`
    if (normalizedPath.startsWith('/')) return `file://${encodedPath}`

    throw new Error(`Original attachment path is not absolute: ${filePath}`)
}

function attachmentMarkdown(files: File[], paths: string[], originalLocation: boolean) {
    return files.map((file, index) => {
        const target = originalLocation ? absoluteFileUrl(paths[index]) : paths[index]
        const label = escapeMarkdownLabel(file.name)

        return file.type.toLowerCase().startsWith('image/')
            ? `![${label}](<${target}>)`
            : `[${label}](<${target}>)`
    }).join('\n')
}

async function restoreCardReferences(cardPath: string, references: string[]) {
    dataService.cards.setCardReferences(cardPath, references)
    await dataService.cards.flushPendingCommits()
}

/** Runs board-card attachment choice and persists resulting references. */
export async function attachFilesToCard(cardPath: string, files: File[]) {
    const selection = await attachmentChoiceService.choose(files)
    if (!selection) return []

    if (selection.choice === 'original') {
        const paths = selection.originalPaths
        if (!paths) throw new Error('Original attachment paths are unavailable')
        dataService.cards.addCardReferences(cardPath, paths)
        await dataService.cards.flushPendingCommits()

        return paths
    }

    const card = dataService.getState().snapshot?.activeCards.find(({ path }) => path === cardPath)
    if (!card) throw new Error(`Cannot attach files to an unloaded card: ${cardPath}`)
    const previousReferences = [...card.header.references]
    const attachments = await copyAndApplyAttachments(
        files,
        (selectedFiles) => dataService.cards.copyAttachmentsForCard(cardPath, selectedFiles),
        async (savedAttachments) => {
            try {
                dataService.cards.addCardReferences(cardPath, savedAttachments.map(({ path }) => path))
                await dataService.cards.flushPendingCommits()
            } catch (error) {
                await restoreCardReferences(cardPath, previousReferences)
                throw error
            }
        },
        (paths) => dataService.cards.deleteCopiedAttachments(paths),
    )

    return attachments.map(({ path }) => path)
}

async function insertCopiedMarkdown(
    files: File[],
    attachments: SavedCardAttachment[],
    insertMarkdown: AttachmentMarkdownInserter,
) {
    await insertMarkdown(attachmentMarkdown(files, attachments.map(({ fileName }) => fileName), false))
}

/** Runs Markdown attachment choice for an existing card-backed editor. */
export async function attachFilesToCardMarkdown(
    cardPath: string,
    files: File[],
    insertMarkdown: AttachmentMarkdownInserter,
) {
    const selection = await attachmentChoiceService.choose(files)
    if (!selection) return

    if (selection.choice === 'original') {
        if (!selection.originalPaths) throw new Error('Original attachment paths are unavailable')
        await insertMarkdown(attachmentMarkdown(files, selection.originalPaths, true))
        return
    }

    await copyAndApplyAttachments(
        files,
        (selectedFiles) => dataService.cards.copyAttachmentsForCard(cardPath, selectedFiles),
        (attachments) => insertCopiedMarkdown(files, attachments, insertMarkdown),
        (paths) => dataService.cards.deleteCopiedAttachments(paths),
    )
}

/** Inserts absolute attachment links when no project copy destination exists. */
export async function attachFilesToOriginalMarkdown(files: File[], insertMarkdown: AttachmentMarkdownInserter) {
    const originalPaths = getOriginalFilePaths(files)
    if (!originalPaths) throw new Error('Original attachment paths are unavailable')

    await insertMarkdown(attachmentMarkdown(files, originalPaths, true))
}

export { attachmentMarkdown }

import { cardFolder, isSafeAssetFileName } from '../../data/asset_paths'
import type { MarkdownFile } from '../../data/data_types'
import { dialogService } from '../dialog_service'
import type { CardOperationContext } from './card_operation_context'

const BASE64_CHUNK_SIZE = 32768
const MAXIMUM_FILE_NAME_ATTEMPTS = 100

export interface SavedCardAttachment {
    fileName: string
    path: string
}

/** Encodes arbitrary browser file bytes for repository storage. */
export async function attachmentBase64(file: File) {
    const bytes = new Uint8Array(await file.arrayBuffer())
    let binary = ''
    for (let offset = 0; offset < bytes.length; offset += BASE64_CHUNK_SIZE) {
        binary += String.fromCharCode(...bytes.subarray(offset, offset + BASE64_CHUNK_SIZE))
    }

    return btoa(binary)
}

function suffixedFileName(fileName: string, suffix: number) {
    const extensionStart = fileName.lastIndexOf('.')
    if (extensionStart <= 0) return `${fileName}-${suffix}`

    return `${fileName.slice(0, extensionStart)}-${suffix}${fileName.slice(extensionStart)}`
}

/** Resolves a collision-safe attachment path beside a card while preserving its base name. */
export function createAvailableAttachmentPath(
    cardPath: string,
    fileName: string,
    existingPaths: Iterable<string>,
): SavedCardAttachment {
    if (!isSafeAssetFileName(fileName)) throw new Error(`Unsafe attachment file name: ${fileName}`)

    const folder = cardFolder(cardPath)
    const normalizedExistingPaths = new Set([...existingPaths].map((path) => path.replace(/\\/gu, '/').toLowerCase()))
    for (let attempt = 0; attempt < MAXIMUM_FILE_NAME_ATTEMPTS; attempt += 1) {
        const availableFileName = attempt === 0 ? fileName : suffixedFileName(fileName, attempt)
        const path = folder.length > 0 ? `${folder}/${availableFileName}` : availableFileName
        if (!normalizedExistingPaths.has(path.toLowerCase())) return { fileName: availableFileName, path }
    }

    throw new Error(`Could not generate an available attachment file name for ${fileName}`)
}

/** Applies references only after copied files persist, cleaning copied files when application fails. */
export async function copyAndApplyAttachments<T>(
    files: File[],
    copyFiles: (files: File[]) => Promise<SavedCardAttachment[]>,
    applyAttachments: (attachments: SavedCardAttachment[]) => T | Promise<T>,
    deleteFiles: (paths: string[]) => Promise<void>,
) {
    const attachments = await copyFiles(files)
    try {
        await applyAttachments(attachments)
    } catch (error) {
        try {
            await deleteFiles(attachments.map(({ path }) => path))
        } catch (cleanupError) {
            dialogService.error(cleanupError, { fallbackMessage: 'Could not remove copied attachments' })
        }
        throw error
    }

    return attachments
}

/** Persists arbitrary copied files without changing clipboard-image behavior. */
export class CardAttachmentOperations {
    private readonly context: CardOperationContext
    private readonly reservedPaths = new Set<string>()

    constructor(context: CardOperationContext) {
        this.context = context
    }

    copyForCard(cardPath: string, files: File[]) {
        return this.copy(cardPath, files)
    }

    copyForNewCard(files: File[]) {
        const { config } = this.context.requireProject('copy an attachment')
        const draftCardPath = `${config.workingFolder}/new-card-draft.md`

        return this.copy(draftCardPath, files)
    }

    async delete(paths: string[]) {
        for (const path of paths) await this.deleteOne(path)
    }

    private async copy(cardPath: string, files: File[]) {
        if (files.length === 0) return []

        const { project } = this.context.requireProject('copy an attachment')
        const existingPaths = [
            ...this.context.dependencies.files().map(({ path }) => path),
            ...(this.context.dependencies.snapshot()?.repositoryFiles ?? []),
            ...this.reservedPaths,
        ]
        const attachments: SavedCardAttachment[] = []
        for (const file of files) {
            const attachment = createAvailableAttachmentPath(cardPath, file.name, existingPaths)
            attachments.push(attachment)
            existingPaths.push(attachment.path)
            this.reservedPaths.add(attachment.path)
        }

        try {
            const attachmentFiles: MarkdownFile[] = []
            for (let index = 0; index < files.length; index += 1) {
                attachmentFiles.push({
                    content: await attachmentBase64(files[index]),
                    encoding: 'base64',
                    path: attachments[index].path,
                })
            }
            await this.context.commitAndMergeFiles({
                branch: project.branch,
                files: attachmentFiles,
                message: attachments.length === 1 ? `Add ${attachments[0].path}` : `Add ${attachments.length} attachments`,
            }, attachmentFiles)
            this.context.dependencies.dispatchPersistenceChanged()
            void this.context.pushCreatedItem(attachments.length === 1 ? 'Attachment' : 'Attachments')

            return attachments
        } finally {
            attachments.forEach(({ path }) => this.reservedPaths.delete(path))
        }
    }

    private async deleteOne(path: string) {
        const { config, project, storage } = this.context.requireProject('delete an attachment')
        const existingFile = this.context.dependencies.files().find((file) => file.path === path)
        const repositoryFile = this.context.dependencies.snapshot()?.repositoryFiles.includes(path) ?? false
        if (!existingFile && !repositoryFile) throw new Error(`Cannot delete an attachment that is not loaded: ${path}`)

        await storage.deleteFile({
            branch: project.branch,
            message: `Delete ${path}`,
            path,
            ...(existingFile?.sha ? { sha: existingFile.sha } : {}),
        })
        this.context.dependencies.deleteFile(path, [], config.workingFolder)
        this.context.dependencies.dispatchChanged()

        if (config.pushMode === 'auto') {
            try {
                await storage.push(project)
            } catch (error) {
                dialogService.error(error, { fallbackMessage: `${path} was deleted locally, but could not be pushed` })
            }
        }
    }
}

const VALUE_CHANGED_EVENT = 'valueChanged'
const EDITOR_CHANGED_EVENT = 'editorChanged'
export const MARKDOWN_INSERTION_REQUESTED_EVENT = 'insertionRequested'

type MarkdownDraftListener = () => void

export interface MarkdownInsertionRequest {
    acknowledge(): void
    markdown: string
    reject(error: unknown): void
}

/** Service-owned Markdown value with external replacement and acknowledged insertion requests. */
export class MarkdownDraft extends EventTarget {
    private editorSnapshot = { replacementRevision: 0 }
    private value: string

    constructor(initialValue: string) {
        super()
        this.value = initialValue
    }

    readonly getSnapshot = () => this.value

    readonly getEditorSnapshot = () => this.editorSnapshot

    readonly subscribe = (listener: MarkdownDraftListener) => {
        this.addEventListener(VALUE_CHANGED_EVENT, listener)

        return () => this.removeEventListener(VALUE_CHANGED_EVENT, listener)
    }

    readonly subscribeEditor = (listener: MarkdownDraftListener) => {
        this.addEventListener(EDITOR_CHANGED_EVENT, listener)

        return () => this.removeEventListener(EDITOR_CHANGED_EVENT, listener)
    }

    edit(value: string) {
        this.setValue(value)
    }

    replace(value: string) {
        this.setValue(value)
        this.editorSnapshot = { replacementRevision: this.editorSnapshot.replacementRevision + 1 }
        this.dispatchEvent(new Event(EDITOR_CHANGED_EVENT))
    }

    clear() {
        if (this.value.length === 0) return

        this.replace('')
    }

    readonly requestInsertion = (markdown: string) => new Promise<void>((resolve, reject) => {
        let handled = false
        const request: MarkdownInsertionRequest = {
            acknowledge: () => {
                if (handled) return
                handled = true
                resolve()
            },
            markdown,
            reject: (error: unknown) => {
                if (handled) return
                handled = true
                reject(error)
            },
        }
        this.dispatchEvent(new CustomEvent<MarkdownInsertionRequest>(MARKDOWN_INSERTION_REQUESTED_EVENT, { detail: request }))
        if (!handled) request.reject(new Error('Markdown insertion requires a mounted editor'))
    })

    private setValue(value: string) {
        if (this.value === value) return

        this.value = value
        this.dispatchEvent(new Event(VALUE_CHANGED_EVENT))
    }
}

