import { useEffect } from 'react'
import {
    MARKDOWN_INSERTION_REQUESTED_EVENT,
    type MarkdownDraft,
    type MarkdownInsertionRequest,
} from '../../services/markdown/markdown_draft'

/** Applies external replacements and insertion requests from one Markdown draft to its mounted editor. */
export function useMarkdownDraft(
    draft: MarkdownDraft | undefined,
    insertMarkdown: (markdown: string) => void,
    replaceMarkdown: (markdown: string) => void,
) {
    useEffect(() => {
        if (!draft) return undefined

        replaceMarkdown(draft.getSnapshot())

        return draft.subscribeEditor(() => replaceMarkdown(draft.getSnapshot()))
    }, [draft, replaceMarkdown])

    useEffect(() => {
        if (!draft) return undefined

        const handleInsertionRequest = (event: Event) => {
            const request = (event as CustomEvent<MarkdownInsertionRequest>).detail
            try {
                insertMarkdown(request.markdown)
                request.acknowledge()
            } catch (error) {
                request.reject(error)
            }
        }
        draft.addEventListener(MARKDOWN_INSERTION_REQUESTED_EVENT, handleInsertionRequest)

        return () => draft.removeEventListener(MARKDOWN_INSERTION_REQUESTED_EVENT, handleInsertionRequest)
    }, [draft, insertMarkdown])
}

import { getOriginalFilePaths } from '../../data/electron_file_bridge'
import { register } from '../service_injector'

export type AttachmentLocationChoice = 'copy' | 'original'

export interface AttachmentChoiceSnapshot {
    fileCount: number
    fileNames: string[]
    originalLocationAvailable: boolean
}

interface PendingAttachmentChoice {
    originalPaths: string[] | null
    resolve: (choice: AttachmentSelection | null) => void
    snapshot: AttachmentChoiceSnapshot
}

export interface AttachmentSelection {
    choice: AttachmentLocationChoice
    originalPaths: string[] | null
}

/** Owns one application-wide attachment location decision. */
export class AttachmentChoiceService extends EventTarget {
    private pending: PendingAttachmentChoice | null = null

    constructor() {
        super()
        register('attachmentChoiceService', this)
    }

    readonly getSnapshot = () => this.pending?.snapshot ?? null

    readonly subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    choose(files: File[]) {
        if (files.length === 0) throw new Error('Cannot choose attachment location without files')
        if (this.pending) throw new Error('Another attachment choice is already open')

        const originalPaths = getOriginalFilePaths(files)
        const snapshot = {
            fileCount: files.length,
            fileNames: files.map(({ name }) => name),
            originalLocationAvailable: originalPaths !== null,
        }

        return new Promise<AttachmentSelection | null>((resolve) => {
            this.pending = { originalPaths, resolve, snapshot }
            this.dispatchEvent(new Event('changed'))
        })
    }

    cancel() {
        this.complete(null)
    }

    select(choice: AttachmentLocationChoice) {
        const pending = this.pending
        if (!pending) throw new Error('No attachment choice is open')
        if (choice === 'original' && !pending.originalPaths) throw new Error('Original file locations are unavailable')

        this.complete({ choice, originalPaths: choice === 'original' ? pending.originalPaths : null })
    }

    private complete(selection: AttachmentSelection | null) {
        const pending = this.pending
        if (!pending) return

        this.pending = null
        pending.resolve(selection)
        this.dispatchEvent(new Event('changed'))
    }
}

export const attachmentChoiceService = new AttachmentChoiceService()

import { Button, Dialog, DialogActions, DialogContent, DialogTitle, Stack, Typography } from '@mui/material'
import { useSyncExternalStore } from 'react'
import { attachmentChoiceService } from '../../services/attachments/attachment_choice_service'

/** Application-wide choice shown once for each file selection or drop. */
export function AttachmentChoiceDialog() {
    const snapshot = useSyncExternalStore(
        attachmentChoiceService.subscribe,
        attachmentChoiceService.getSnapshot,
        attachmentChoiceService.getSnapshot,
    )
    const cancel = () => attachmentChoiceService.cancel()
    const copy = () => attachmentChoiceService.select('copy')
    const useOriginal = () => attachmentChoiceService.select('original')

    return (
        <Dialog aria-labelledby="attachment-choice-title" onClose={cancel} open={snapshot !== null}>
            <DialogTitle id="attachment-choice-title">
                Attach {snapshot?.fileCount ?? 0} file{snapshot?.fileCount === 1 ? '' : 's'}
            </DialogTitle>
            <DialogContent>
                <Stack spacing={1.5}>
                    <Typography color="text.secondary">
                        Copy into project saves a copy next to the card, so it stays with the project.
                        Link without copying keeps each file where it is and links to it using its full path.
                    </Typography>
                    {!snapshot?.originalLocationAvailable ? (
                        <Typography color="text.secondary" role="status" variant="caption">
                            Linking without copying is unavailable because this browser cannot access the files&apos; full paths.
                        </Typography>
                    ) : null}
                </Stack>
            </DialogContent>
            <DialogActions sx={{ bgcolor: 'background.default', borderTop: 1, borderColor: 'divider' }}>
                <Button onClick={cancel} variant="outlined">Cancel</Button>
                <Button disabled={!snapshot?.originalLocationAvailable} onClick={useOriginal} variant="outlined">
                    Link without copying
                </Button>
                <Button onClick={copy} variant="contained">Copy into project</Button>
            </DialogActions>
        </Dialog>
    )
}

